<script setup>
import { computed, onMounted, ref, watch } from 'vue';
import { ArrowLeft, Upload, Pencil, UserRound, Users, UserRoundPlus, Search, X, ClipboardList, Sparkles, Zap, ChevronRight } from 'lucide-vue-next';
import AutoLabel from './AutoLabel.vue';
import UiButton from './UiButton.vue';
import UiBadge from './UiBadge.vue';
import RoomArt from './RoomArt.vue';
import { assignPreviewMedia } from '../previewState.js';
import { loadLabellers, loadRoles, loadAssignment, api } from '../api/annotate.js';
const props=defineProps({batch:Object,state:Object,project:Object,startMode:String});
const emit=defineEmits(['close','upload','rename','edit','auto','assigned','professional']);
const mode=ref(props.startMode||(props.state.live?'auto':'choose')),query=ref(''),memberQuery=ref(''),sort=ref('Newest'),quantity=ref(props.state.images.filter(i=>i.batchId===props.batch.id).length),shuffle=ref(true),instructions=ref(props.batch.instructions||''),instructionsOpen=ref(false),inviteOpen=ref(false),inviteName=ref(''),email=ref(''),role=ref('Labeler'),error=ref(''),feedback=ref(''),selected=ref('Me');
// Live (the Annotate board of a real project): the people who may label, the backend's roles, real assignments.
const live=computed(()=>!!props.state.live);
const busy=ref(false);const roles=ref([]);
// Invite (live): the whole project with a role, or only this batch (a Labeller); and this batch's photos to label with it.
const inviteScope=ref('project');const inviteAssign=ref(false);
watch(inviteScope,s=>{if(s==='batch')inviteAssign.value=true;});
const media=computed(()=>props.state.images.filter(i=>i.batchId===props.batch.id));
const shown=computed(()=>{const a=media.value.filter(i=>i.name.toLowerCase().includes(query.value.toLowerCase()));return sort.value==='Name A-Z'?[...a].sort((a,b)=>a.name.localeCompare(b.name)):sort.value==='Newest'?[...a].reverse():a;});
const members=computed(()=>live.value?(props.state.labellers||[]).map(p=>({key:p.id,name:p.you?`${p.name} (you)`:p.name,sub:p.role_label,you:p.you})):['Me','Demo labeller'].map(m=>({key:m,name:m,sub:m==='Me'?'Current user':'Sample project member',you:m==='Me'})));
const visibleMembers=computed(()=>members.value.filter(m=>m.name.toLowerCase().includes(memberQuery.value.toLowerCase())));
const drafts=computed(()=>props.state.invitationDrafts||[]);
const roleHelp=computed(()=>live.value?(roles.value.find(r=>r.value===role.value)?.help||''):(role.value==='Admin'?'Manage project and members.':role.value==='Reviewer'?'Review labels and request changes.':'Annotate assigned media.'));
onMounted(async()=>{if(!live.value)return;try{const people=await loadLabellers(props.state);selected.value=(people.find(p=>p.you)||people[0])?.id??'';}catch(e){error.value=e.message;}try{roles.value=await loadRoles(props.state);role.value=roles.value.find(r=>r.value==='labeller')?.value||roles.value[0]?.value||'';}catch{roles.value=[];}});
async function saveInvite(){error.value='';const name=inviteName.value.trim();if(!name){error.value='Enter the team member name.';return;}const value=email.value.trim().toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)){error.value='Enter a valid email address.';return;}
  if(live.value){busy.value=true;try{const withBatch=inviteScope.value==='batch'||inviteAssign.value;const body=await api.invite(props.state.ref,{name,email:value,role:role.value,scope:inviteScope.value,assign:withBatch?{source:props.batch.source,size:Number(quantity.value),shuffle:shuffle.value,instructions:instructions.value,name:props.batch.name}:undefined});feedback.value=body.message;inviteName.value='';email.value='';}catch(e){error.value=e.message;}finally{busy.value=false;}return;}
  props.state.invitationDrafts??=[];if(drafts.value.some(d=>d.email===value)){error.value='An invitation draft already exists for this email.';return;}props.state.invitationDrafts.push({name,email:value,role:role.value,projectId:props.project?.id,status:'Draft - not sent'});inviteName.value='';email.value='';feedback.value='Draft saved locally. No email was sent and no access was granted.';}
// Auto Label: the chosen model becomes this person's choice for a photo nobody has drawn on, then the batch is given
// to them and the editor opens; each photo opens with the model's walls as a head start (api: detect-preference/).
async function autoLabel(source){error.value='';busy.value=true;try{await api.detectPreference(props.state.ref,source);}catch(e){error.value=e.message;busy.value=false;return;}busy.value=false;await start(true);}
async function start(manual=false){error.value='';
  if(live.value){const me=members.value.find(m=>m.you);const labeller=manual?me?.key:selected.value;if(!labeller){error.value=manual?'Your role in this project does not let you label photos.':'Choose who labels these photos.';return;}
    busy.value=true;try{const row=await api.createAssignment(props.state.ref,{source:props.batch.source,labeller,size:manual?media.value.length:Number(quantity.value),shuffle:manual?false:shuffle.value,instructions:instructions.value,name:props.batch.name});const job=await loadAssignment(props.state,{id:`a${row.number}`,kind:'assignment',number:row.number});emit('assigned',job,{edit:manual});}catch(e){error.value=e.message;}finally{busy.value=false;}return;}
  try{emit('assigned',assignPreviewMedia(props.state,props.batch.id,{count:manual?media.value.length:Number(quantity.value),assignee:manual?'Me':selected.value,instructions:instructions.value,shuffle:manual?false:shuffle.value}));}catch(e){error.value=e.message;}}
</script>
<template>
<div class="unassigned-layout"><AutoLabel v-if="live&&mode==='auto'" :batch="batch" :state="state" :media="media" :busy="busy" @close="emit('close')" @autolabel="autoLabel"/><section v-else class="unassigned-main"><header><div><button class="team-back" @click="emit('close')"><ArrowLeft :size="14"/>Annotate</button><h2>Unassigned Media</h2><UiBadge>Batch: {{batch.name}}</UiBadge><span v-if="batch.code" class="batch-code" title="Reference code of this batch">{{batch.code}}</span></div><div class="unassigned-actions"><UiButton @click="emit('upload')"><Upload :size="15"/>Upload More</UiButton><UiButton @click="emit('rename')"><Pencil :size="15"/>Rename</UiButton></div></header>
<div class="unassigned-filters"><label class="media-search"><Search :size="16"/><input v-model="query" aria-label="Search batch media" placeholder="Search images..."/></label><select v-model="sort" aria-label="Sort unassigned media"><option>Newest</option><option>Oldest</option><option>Name A-Z</option></select></div>
<div class="unassigned-images"><button v-for="image in shown" :key="image.id" @click="emit('edit',image)"><div><RoomArt v-if="image.sample" plain :variant="image.variant||0"/><img v-else :src="image.url" :alt="image.name"/></div><span :title="image.name">{{image.name}}</span></button></div><p v-if="!shown.length">No images match your search.</p><footer>{{shown.length}} of {{media.length}} images<template v-if="!live"> &middot; Local preview</template></footer></section>
<aside class="labeling-sidebar"><template v-if="mode!=='team'"><p class="choice-crumb">Batch / Choose how to label this batch</p><button :class="['label-choice',{chosen:mode==='auto'}]" :aria-pressed="mode==='auto'" @click="live?mode='auto':emit('auto')"><Zap :size="22"/><span><strong>Auto Label <UiBadge tone="purple">Recommended</UiBadge></strong><p>Let a model mark the walls, windows and doors first; you check them. Minutes, not hours.</p></span></button><button class="label-choice" :disabled="busy" @click="start(true)"><UserRound :size="22"/><span><strong>Label manually</strong><p>Create labels one photo at a time, in the editor.</p></span></button><button class="label-choice" @click="mode='team'"><Users :size="23"/><span><strong>Label with your team</strong><p>Split the labeling work across your team.</p></span><ChevronRight class="choice-more" :size="16"/></button><button class="label-choice" @click="emit('professional')"><Users :size="23"/><span><strong>Label with a professional team</strong><p>Work with professional labelers.</p><UiBadge>Coming soon</UiBadge></span></button></template>
<template v-else><button class="team-back" @click="mode='choose';inviteOpen=false"><ArrowLeft :size="13"/>Choose / Label With My Team</button><div class="assign-count"><label>Total Media to Assign <span><input v-model.number="quantity" type="number" min="1" :max="media.length" aria-label="Total media to assign"/> / {{media.length}}</span></label><input v-model.number="quantity" type="range" min="1" :max="Math.max(1,media.length)" aria-label="Assignment media count"/><label class="shuffle"><input v-model="shuffle" type="checkbox"/>Shuffle media when assigning</label></div>
<UiButton @click="instructionsOpen=!instructionsOpen"><ClipboardList :size="15"/>{{instructionsOpen?'Hide Instructions':'Add Instructions'}}</UiButton><label v-if="instructionsOpen" class="field-label">Labeling instructions<textarea v-model="instructions" class="text-input" rows="4" maxlength="1000"/></label>
<div class="team-search"><label class="media-search"><Search :size="16"/><input v-model="memberQuery" aria-label="Search team members" placeholder="Search for team members..."/></label><button class="icon-button" :aria-label="inviteOpen?'Close invitation form':'Invite team member'" @click="inviteOpen=!inviteOpen;error='';feedback=''"><X v-if="inviteOpen" :size="18"/><UserRoundPlus v-else :size="18"/></button></div>
<form v-if="inviteOpen" class="invite-form" @submit.prevent="saveInvite"><h3><UserRoundPlus :size="17"/>Invite Team Member</h3><p>Project: {{project?.name||batch.name}}</p><label class="field-label">Full name (required)<input v-model="inviteName" class="text-input" type="text" required maxlength="100" autocomplete="name" aria-label="Team member name" placeholder="Enter full name"/></label><fieldset v-if="live" class="invite-scope"><legend>Access</legend><label class="shuffle"><input v-model="inviteScope" type="radio" value="project"/>Whole project</label><label class="shuffle"><input v-model="inviteScope" type="radio" value="batch"/>Only this batch</label></fieldset><div class="invite-fields"><input v-model="email" type="email" required maxlength="254" aria-label="Team member email" placeholder="name@example.com"/><select v-if="!live||inviteScope==='project'" v-model="role" aria-label="Invitation role"><template v-if="live"><option v-for="r in roles" :key="r.value" :value="r.value">{{r.label}}</option></template><template v-else><option>Labeler</option><option>Reviewer</option><option>Admin</option></template></select></div><small>{{live&&inviteScope==='batch'?'They see and label only the photos given to them: this batch.':roleHelp}}<template v-if="!live"> Proposed role only.</template></small><label v-if="live" class="shuffle"><input v-model="inviteAssign" type="checkbox" :disabled="inviteScope==='batch'"/>Give them this batch to label ({{quantity}} photo{{Number(quantity)===1?'':'s'}}{{shuffle?', shuffled':''}})</label><template v-if="live"><UiButton type="submit" variant="primary" :disabled="busy">{{busy?'Sending…':'Send Invite'}}</UiButton></template><template v-else><UiButton type="submit">Save invitation draft</UiButton><UiButton type="button" disabled>Send Invite &middot; Coming soon</UiButton><UiBadge>Coming soon</UiBadge></template></form>
<div class="team-members"><button v-for="member in visibleMembers" :key="member.key" :class="{chosen:selected===member.key}" :aria-pressed="selected===member.key" @click="selected=member.key"><span class="member-avatar">{{member.name[0]}}</span><span><strong>{{member.name}}</strong><small>{{member.sub}}</small></span><UiBadge v-if="selected===member.key">{{quantity}}</UiBadge></button><p v-if="!visibleMembers.length">No matching members. Use the invite button to prepare an invitation.</p></div>
<div v-if="!live&&drafts.length" class="invite-drafts"><h3>Invitation drafts</h3><article v-for="draft in drafts" :key="draft.email"><strong>{{draft.name||draft.email}}</strong><small v-if="draft.name">{{draft.email}}</small><small>{{draft.role}} &middot; {{draft.status}}</small></article><p>Draft invitees cannot be assigned media.</p></div>
<div class="assign-footer"><p>{{live?'The chosen person gets the photos and a notification.':'Session-only preview. No jobs or notifications are sent.'}}</p><UiButton variant="primary" :disabled="busy||!media.length||!Number.isInteger(Number(quantity))||Number(quantity)<1||Number(quantity)>media.length" @click="start()">Start Annotating</UiButton></div></template><p v-if="error" class="assignment-error" role="alert">{{error}}</p><p v-if="feedback" role="status">{{feedback}}</p></aside></div>
</template>
<style scoped>
.unassigned-layout{display:grid;grid-template-columns:minmax(0,1fr) 360px;background:white;border:1px solid #e0e3eb;border-radius:8px;overflow:hidden;min-height:700px}.unassigned-main{min-width:0;display:flex;flex-direction:column}.unassigned-main>header{display:flex;justify-content:space-between;gap:16px;padding:25px 24px;border-bottom:1px solid #e0e3eb;align-items:flex-start}.team-back{display:flex;align-items:center;gap:7px;border:0;background:none;color:#657890;font-size:12px;padding:0}.unassigned-main h2{font-size:21px;font-weight:600;margin:13px 0 10px}.unassigned-actions{display:flex;gap:8px}.unassigned-filters{display:flex;gap:10px;flex-wrap:wrap;padding:18px 24px}.media-search{display:flex;align-items:center;gap:7px;border:1px solid #d3d9e5;border-radius:7px;padding:9px 11px;color:#7d899c;min-width:0}.media-search:focus-within{outline:2px solid var(--aadml-outline)}.media-search input{border:0;outline:none;min-width:0;width:100%;background:none;font-size:13px}select,.invite-fields>input{border:1px solid #d2d8e3;border-radius:6px;padding:9px 10px;background:white;color:#405570;font-size:13px;min-width:0}.unassigned-images{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:26px;padding:12px 24px 30px}.unassigned-images>button{border:0;background:none;text-align:left;padding:0;min-width:0}.unassigned-images>button>div{height:125px;border:2px solid transparent;border-radius:7px;overflow:hidden;background:#f2f4f7}.unassigned-images img,.unassigned-images svg{width:100%;height:100%;object-fit:cover}.unassigned-images>button:hover>div{border-color:var(--aadml-focus)}.unassigned-images>button>span{display:block;font-size:12px;color:#677b95;margin-top:7px;white-space:nowrap;text-overflow:ellipsis;overflow:hidden}.unassigned-main>footer{margin-top:auto;border-top:1px solid #e0e3eb;padding:18px 24px;font-size:12px;color:#6a7b92}.labeling-sidebar{border-left:1px solid #d5dae4;padding:22px 20px;display:flex;flex-direction:column;gap:12px}.labeling-sidebar>p{font-size:13px}.label-choice{display:flex;align-items:flex-start;text-align:left;gap:12px;padding:15px 12px;background:white;border:1px solid #dfe3eb;border-radius:8px;color:#233b59;width:100%}.label-choice>svg{flex-shrink:0;color:#637389;margin-top:3px}.label-choice strong{font-size:15px;font-weight:500}.label-choice p{font-size:13px;line-height:1.5;margin-top:5px}.label-choice:hover,.label-choice.chosen{background:var(--aadml-tint);border-color:var(--aadml-focus)}.label-choice.chosen strong{color:var(--aadml-primary)}.label-choice>span{flex:1}.label-choice strong{display:flex;align-items:center;justify-content:space-between;gap:8px}.label-choice strong .badge{margin-top:0}.choice-more{align-self:center;color:#8b95a7}.choice-crumb{font-size:12px!important;color:#6d7c92}.label-choice .badge{margin-top:8px}.assign-count{padding:14px;background:#f8f9fb;border-radius:8px}.assign-count>label:first-child{display:flex;align-items:center;justify-content:space-between;font-size:13px;gap:8px}.assign-count input[type=number]{width:58px;border:1px solid #d2d8e3;border-radius:6px;padding:6px;text-align:right}.assign-count input[type=range]{width:100%;margin:17px 0 10px;accent-color:var(--aadml-primary)}.shuffle{display:flex;gap:8px;font-size:13px;color:#506987}.shuffle input{accent-color:var(--aadml-primary)}.team-search{display:flex;gap:8px}.team-search .media-search{flex:1}.team-search>.icon-button{border:1px solid #d5dbe5;border-radius:6px;background:#f7f8fa;width:36px;flex-shrink:0}.invite-form{border:1px solid #dfe2eb;border-radius:8px;padding:12px;display:flex;flex-direction:column;gap:10px}.invite-form h3{font-size:14px;display:flex;align-items:center;gap:6px}.invite-form>p{font-size:11px}.invite-fields{display:grid;grid-template-columns:minmax(0,1fr) 100px;gap:8px}.invite-form small{font-size:11px;line-height:1.5;color:#74839b}.team-members{display:flex;flex-direction:column;gap:8px}.team-members>button{display:flex;align-items:center;gap:10px;border:1px solid #dce1eb;border-radius:8px;background:white;padding:12px;text-align:left;width:100%}.team-members>button.chosen{border-color:var(--aadml-primary);background:var(--aadml-tint)}.member-avatar{display:grid;place-items:center;width:34px;height:34px;flex-shrink:0;background:#005d50;border-radius:50%;color:#fff}.team-members strong{font-size:12px;font-weight:500}.team-members small{display:block;font-size:11px;color:#728098;margin-top:4px}.team-members .badge{margin-left:auto}.team-members>p{font-size:12px}.assign-footer{margin-top:auto;padding-top:30px}.assign-footer .button{width:100%}.assign-footer>p{font-size:11px;margin-bottom:8px}.invite-drafts h3{font-size:13px;margin:14px 0 8px}.invite-drafts article{padding:10px;border:1px solid #e1e4ec;border-radius:7px;margin-bottom:7px;overflow-wrap:anywhere}.invite-drafts strong,.invite-drafts small{display:block;font-size:11px}.invite-drafts small,.invite-drafts p{color:#7d899a;font-size:11px;margin-top:5px}.assignment-error{color:#ba354e}@media(max-width:1100px){.unassigned-layout{grid-template-columns:minmax(0,1fr) 320px}.unassigned-main>header{flex-wrap:wrap}}@media(max-width:800px){.unassigned-layout{grid-template-columns:1fr}.labeling-sidebar{border-left:0;border-top:1px solid #ddd}.unassigned-images{grid-template-columns:repeat(2,minmax(0,1fr))}.assign-footer{padding-top:20px}}
.invite-scope{border:0;padding:0;margin:4px 0 0;display:flex;gap:16px;flex-wrap:wrap}.invite-scope legend{font-size:12px;font-weight:600;margin-bottom:4px}
</style>
